INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1314504-che470', 'stk-moeaya', 'CHE 470', 'info', '{"desc": "خفيف وسهل وحلو الكورس\nمافيه تعقيد كثير\nقوانين وتعوض وتحسب\nحلو جدا انه متنوع وكل تشابتر عن شي\nاخدته 131 مع الدكتور البطل محمد باشماخ\n2 ميجر\nفاينل\nبروجكت 10 في المية عن اي شي في المنهج\nو3 كويزات وهوم ورك واحد او اثنين بس\nماتحس انك منزله مادة وتشيل همها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-470-process-air-pollution-control/148264/2", "user": "moeaya", "ts": 1388797572000, "tid": 148264, "pn": 2}}', 1388797572000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316669-che470', 'stk-user4195', 'CHE 470', 'info', '{"desc": "Process Air Pollution Control\n\nعند الدكتور باشماخ\n\nالمادة ما لها علاقة بال 401\n\nكتابها جيد وماتيريال حقها طويل نوعاً ما … ماتيريال ميجر ١ سهل جداً وماتيريال ميجر ٢ نص ونص وماتيريال الفاينل صعب … مشكلة الإختبارات فيها إن فيها صح وخطأ وشغل الثانوية يذكر لك جمله من الكتاب بالنص ويحذف كلمة منها ويحطها لك :\\\n\nميزتها ما راح تشغلك ابد طول السمستر حتى البروجكت شغل كم ساعه وقروب بعد\n\nالفائدة الي بتطلع منها من المادة إنك بتتعلم الأجهزة المستخدمة للتحكم بالإنبعاثات أنواعها و الديزاين للأجهزة المستخدمة\n\nمادة انصح فيها لأي واحد مضغوط في سمستره الأخير\n\nواخيرا لو اعطيتها حقها بتطلع بقريد محترم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-470-process-air-pollution-control/148264/3", "user": "user4195", "ts": 1389101237000, "tid": 148264, "pn": 3}}', 1389101237000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1322676-che470', 'stk-chemist', 'CHE 470', 'info', '{"desc": "جودة المقرر بشكل عام:\nهذا الكورس مهم جدا لطلاب الهندسة المدنية والكيميائية معا. يعد هذا الكورس فرع مستقل بذاته من فروع الهندسة الكيميائية وهو يتكلم عن كيفية التحكم في تلوث الهواء والتحكم أيضا في انبعاث الغازات المختلفة. إذا حبيت تكمل في هذا المجال راح تسمى مهندس بيئيEnvironmental Engineer أو مهندس التحكم في تلوث الهواء Air pollution control engineer.\n\nالمواضيع التي يغطيها المقرر:\n1) مقدمة عن تلوث الهواء وعن التعريفات والمفاهيم الأساسية للتلوث. ظاهرة الإحتباس الحراري و أسباب الثقب في طبقة الأوزون وغيرها.\n2) مقدمة عن الجسميات الصغيرة الموجودة في الهواء ( Particulate Matter ) مثل الغبار وطرق السيطرة عليها وعزلها عن الهواء بعدة أجهزة مختلفة مثل Cyclone, Electorstatic Precipitator, Fabric Filter, Particulate Scrubber طبعا كل واحد من هذه الأجهزة له Chapter لحاله.\n3) مقدمة عن محرق المركبات العضوية المتطايرة ( VOC Incinerators ) وكيفية عملة والتحدث عن التفاعلات التي تتم فيه.\n4) التخلص من الغازات بواسطة الإدمصاص ( Adsorption ) و الإمتصاص ( Absorption )\n5) علاقة تلوث الهواء بأحوال المناخ وكيف ان الرياح ممكن تزيد من سرعة وكمية المواد السامة المنبعثة من المصانع الكيميائية.\n6) Atmospheric Dispersion modeling\n7) التحكم في تلوث CO2 + NOx + SOx\n\nالكتاب المستخدم:\nAir Pollution Control: A Design Approach\nhttp://i43.tower.com/images/mm118028346/air-pollution-control-design-approach-c-david-cooper-hardcover-cover-art.jpg\n\nتقييم الكتاب:\nمميزات الكتاب:\n1) لغته سهلة جدا.\n2) بسيط وما فيه فلسفه واجد تعور الراس.\n3) ترتيب وتسلسل جيد للمواضيع.\n4) الأمثلة والتمارين متوفرة بكثرة ومستواها سهل ومو معقد.\nعيوب الكتاب:\n1) مؤلفين الكتاب مهندسيين مدنيين فلو كانوا كيميائيين أعتقد ان الفائدة راح تكون أكبر.\n2) الإخراج قديم ويحتاج إلى تطوير وتنسيق بشكل أفضل.\n\nأنتهى 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-470-process-air-pollution-control/148264/4", "user": "Chemist", "ts": 1390762833000, "tid": 148264, "pn": 4}}', 1390762833000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-che470', 'stk-user6661', 'CHE 470', 'doc', '{"docs": [{"id": "stk-dr-f115340", "n": "Dr. M Ba-Shammakh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che 470 - ترم 131\n\nيحضر يوميا في بداية كل كلاس …\n\nخلوق جدا وشريح ونوته ممتاز و\"شبه\" شامل …\n\nجيد في الشرح …\n\nاختباراته تقريبا مستواها متوسط …\n\nوالقريدات كانت مرضية جدا , انصح فيه …\n\nبالتوفيق 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1317929-che470", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-ba-shammakh/115340/7", "user": "user6661", "ts": 1389319214000, "tid": 115340, "pn": 7}}]}', 1389319214000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-che470', 'stk-chemist', 'CHE 470', 'doc', '{"docs": [{"id": "stk-dr-f115340", "n": "Dr. M Ba-Shammakh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 470 - Term 131\n\nالتحضير:\nكل محاضرة وانسى انه ينسى 😆. لو تجي متأخر يعني بعد 20 دقيقة أعتقد مايحضرك ويحطك غايب ولكن تقدر تدخل الكلاس وتسمع للدرس.\n\nطريقة الشرح:\nالدكتور محمد فاهم والمادة هذي هي قلب تخصصه وهو التحكم في تلوث الهواء ولكن طريقة شرح الدكتور مملة نوعا ما. يشرح لك كنك طالب في الثانوية يكتب نوت والطلاب يكتبون نوت معاه ونوته كوبي بيس من الكتاب إلا في بعض الحاجات القليلة. ما عمره استخدم البوربوينت أو أي من وسائل الشرح الحديثة. بالنسبة للمسائل فشرحه فيها ممتاز يحل الصعبة بالتفصيل والسهلة يقول لنا فكرتها بس وأشوف انه ممتاز جدا في حل المسائل.\n\nالكويزات:\nسهلة ومو صعبة ونفس أفكار الكتاب.\n\nالمياجر:\nمتوسطة ونفس أفكار المسائل اللي في الكتاب.\n\nالفاينال:\nنفس مستوى مياجرة وكان متوسط و شامل لكل المنهج.\n\nالواجبات:\nسهلة وتكون من الكتاب ولا يعطي واجبات واجد يعني مايكرفك 😆.\n\nالتصحيح وتوزيع القريدات:\nتصحيحه حقاني وحلو متى يحس أو يشم انك فاهم يعطيك قريد. أما توزيعه أو تقسيمه للفاينال القريد فكان ممتاز جدا. كان الفاينال أفرج عنده بي وعطى الطلاب قريدات ممتازه جدا.\n\nمميزات الدكتور:\n1) حبيب وخلوق ومتعاون.\n2) فاهم ويقدر يوصل المعلومة بكل أريحية.\n3) يحب يكون في صف الطالب.\n4) قريداته حلوة\n\nالعيوب:\n1) أكبر عيب هي طريقة الشرح القديمة اللي ما أعجبتني صراحة.\n2) مدري بس أحس انه ما يصلح للمواد الكومون.\n\nالقريد النهائي للدكتور:\nB", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1322236-che470", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-ba-shammakh/115340/8", "user": "Chemist", "ts": 1390698348000, "tid": 115340, "pn": 8}}]}', 1390698348000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
